import * as THREE from './vendor/three.module.js';
import {GeometryBuilder} from './lowpoly.js';
function vanGeometry(){const b=new GeometryBuilder();b.box('#edf0df',0,1.15,0,1.9,1.45,4.1).box('#e4e9d8',0,.82,1.95,1.85,.8,.65).box('#e4e9d8',0,1.9,-.5,1.9,.12,2.9);b.plane('#58787c',0,1.52,2.057,1.55,.58);for(const x of [-.958,.958]){b.plane('#557477',x,1.54,1.25,.8,.55,0,Math.sign(x)*Math.PI/2).plane('#739484',x,1.05,-.45,2.75,.30,0,Math.sign(x)*Math.PI/2);}b.box('#dbaa47',0,2.01,.6,.6,.22,.32).box('#53695c',0,.48,2.28,1.84,.16,.11);for(const x of [-.68,.68])b.box('#ffe9ad',x,.93,2.3,.3,.19,.04);const wheel=new THREE.CylinderGeometry(.39,.39,.23,8);for(const x of [-.94,.94])for(const z of [-1.35,1.35])b.add(wheel,'#465448',x,.43,z,1,1,1,0,0,Math.PI/2);wheel.dispose();return b.build();}
function workerGeometry(){const b=new GeometryBuilder();b.box('#dbad50',0,1.05,0,.48,.65,.28);for(const x of [-.15,.15])b.box('#465d60',x,.43,0,.18,.75,.22);for(const x of [-.34,.34])b.box('#d2a286',x,1.05,0,.15,.60,.17);const head=new THREE.IcosahedronGeometry(.21,0);b.add(head,'#d8af8e',0,1.56,0);head.dispose();b.box('#f1c85c',0,1.74,0,.48,.10,.39);b.plane('#f5eccc',0,1.10,.151,.38,.08);return b.build();}
export const READ_COLOR={read:'#4f9d5d',flagged:'#e2a43a',missed:'#d24b3f',not_due:'#9fb1bd',none:'#9fb1bd'};
export class OperationsView{
 constructor(root,ops,heightAt){this.ops=ops;this.heightAt=heightAt;this.group=new THREE.Group();root.add(this.group);const material=new THREE.MeshStandardMaterial({vertexColors:true,roughness:.85});this.vans=new THREE.InstancedMesh(vanGeometry(),material,64);this.workers=new THREE.InstancedMesh(workerGeometry(),material,64);for(const m of [this.vans,this.workers]){m.count=0;m.frustumCulled=false;this.group.add(m);}this.rings=new THREE.InstancedMesh(new THREE.RingGeometry(4,5,24),new THREE.MeshBasicMaterial({color:'#e1784d',transparent:true,opacity:.8,side:THREE.DoubleSide,depthTest:false}),128);this.rings.count=0;this.rings.frustumCulled=false;this.group.add(this.rings);this.puddles=new THREE.InstancedMesh(new THREE.CircleGeometry(4,16),new THREE.MeshBasicMaterial({color:'#62c4da',transparent:true,opacity:.65,side:THREE.DoubleSide}),128);this.puddles.count=0;this.puddles.frustumCulled=false;this.group.add(this.puddles);const b=new GeometryBuilder(),jet=new THREE.CylinderGeometry(.13,.32,4,5);b.add(jet,'#a9e4e9',0,2,0,1,1,1,0,0,.1);b.add(jet,'#82cddc',.65,1.6,0,.8,.8,.8,0,0,-.4);jet.dispose();this.jets=new THREE.InstancedMesh(b.build(),material,128);this.jets.count=0;this.jets.frustumCulled=false;this.group.add(this.jets);this.dummy=new THREE.Object3D();this.vanIds=[];
  // Meter reads on reading rounds, once the reader has passed: green read, amber flagged by VEE, red missed.
  this.homes=new Map((ops.town?.premises||[]).map(h=>[h.id,h]));this.reads=new THREE.InstancedMesh(new THREE.CircleGeometry(1.5,14),new THREE.MeshBasicMaterial({transparent:true,opacity:.92,side:THREE.DoubleSide,depthTest:false,toneMapped:false}),Math.max(1,Math.min(4096,this.homes.size)));this.reads.count=0;this.reads.frustumCulled=false;this.reads.renderOrder=3;this.group.add(this.reads);this.color=new THREE.Color();}
 update(){let vans=0,workers=0,rings=0,water=0;this.vanIds=[];for(const job of this.ops.jobs){const state=this.ops.jobState(job);if(['future','completed'].includes(state.status)||vans>=64)continue;const p=state.position,d=this.dummy;d.position.set(p.x,this.heightAt(p.x,p.z)+.12,p.z);d.rotation.set(0,Math.atan2(p.dx||0,p.dz||1),0);d.scale.setScalar(1.5);d.updateMatrix();this.vans.setMatrixAt(vans++,d.matrix);this.vanIds.push(job.id);if(state.agent){d.position.set(state.agent.x,this.heightAt(state.agent.x,state.agent.z)+.15,state.agent.z);d.scale.setScalar(1.8);d.updateMatrix();this.workers.setMatrixAt(workers++,d.matrix);}}
  for(const i of this.ops.incidents){if(!this.ops.active(i)||rings>=128)continue;const d=this.dummy;d.position.set(i.x,this.heightAt(i.x,i.z)+.35,i.z);d.rotation.set(-Math.PI/2,0,0);d.scale.setScalar(1);d.updateMatrix();this.rings.setMatrixAt(rings++,d.matrix);if(i.utility==='water'){this.puddles.setMatrixAt(water,d.matrix);d.rotation.set(0,0,0);d.updateMatrix();this.jets.setMatrixAt(water++,d.matrix);}}
  let reads=0;const t=this.ops.time,cap=this.reads.instanceMatrix.count;for(const job of this.ops.jobs){if(!job.stops||job.startAt>t)continue;for(const s of job.stops){if(s.at>t||reads>=cap)break;const h=this.homes.get(s.premiseId);if(!h)continue;const p=h.front||h,d=this.dummy;d.position.set(p.x,this.heightAt(p.x,p.z)+.32,p.z);d.rotation.set(-Math.PI/2,0,0);d.scale.setScalar(1);d.updateMatrix();this.reads.setMatrixAt(reads,d.matrix);this.reads.setColorAt(reads++,this.color.set(READ_COLOR[s.outcome]||READ_COLOR.none));}}
  this.readCount=reads;if(this.reads.instanceColor)this.reads.instanceColor.needsUpdate=true;
  for(const [mesh,count]of [[this.vans,vans],[this.workers,workers],[this.rings,rings],[this.puddles,water],[this.jets,water],[this.reads,reads]]){mesh.count=count;mesh.instanceMatrix.needsUpdate=true;}
 }
}
